L["help.keyboard"] = "Mouse wheel or the row controls scroll results. Tab and Shift+Tab move focus; arrow keys select results; Enter activates results; Escape closes the zone or sub-group picker, dialogs, then the directory."
L["help.commands"] = "Commands: /monstrator, /monstrator help, /monstrator zone NAME, /monstrator region NAME, /monstrator find TEXT, /monstrator items NAME, /monstrator model, /monstrator scan [add|remove|list|on|off|rares|sound|test], /monstrator reset, /monstrator discover, /monstrator capture, /monstrator journal, /monstrator npcs, /monstrator audit, /monstrator sync world, /monstrator export, /monstrator diagnostic."
